class TaskManager {
  constructor() {
    this.tasks = [];
    this.currentFilter = 'all';
    this.init();
  }

  init() {
    this.loadTasks();
    this.bindEvents();
    this.render();
  }

  // Load tasks from localStorage
  loadTasks() {
    const savedTasks = localStorage.getItem('tasks');
    if (savedTasks) {
      this.tasks = JSON.parse(savedTasks);
    }
  }

  // Save tasks to localStorage
  saveTasks() {
    localStorage.setItem('tasks', JSON.stringify(this.tasks));
  }

  // Add a new task
  addTask(text) {
    if (!text.trim()) return;

    const task = {
      id: Date.now(),
      text: text.trim(),
      completed: false,
      timestamp: new Date().toISOString()
    };

    this.tasks.push(task);
    this.saveTasks();
    this.render();
  }

  // Toggle task completion status
  toggleTask(id) {
    const task = this.tasks.find(task => task.id === id);
    if (task) {
      task.completed = !task.completed;
      this.saveTasks();
      this.render();
    }
  }

  // Delete a task
  deleteTask(id) {
    const taskElement = document.querySelector(`[data-id='${id}']`);
    if (taskElement) {
      taskElement.classList.add('slide-out');
      setTimeout(() => {
        this.tasks = this.tasks.filter(task => task.id !== id);
        this.saveTasks();
        this.render();
      }, 300);
    }
  }

  // Clear completed tasks
  clearCompleted() {
    this.tasks = this.tasks.filter(task => !task.completed);
    this.saveTasks();
    this.render();
  }

  // Set current filter
  setFilter(filter) {
    this.currentFilter = filter;
    this.render();
  }

  // Get filtered tasks
  getFilteredTasks() {
    switch (this.currentFilter) {
      case 'active':
        return this.tasks.filter(task => !task.completed);
      case 'completed':
        return this.tasks.filter(task => task.completed);
      default:
        return this.tasks;
    }
  }

  // Bind event listeners
  bindEvents() {
    const taskInput = document.getElementById('task-input');
    const addTaskBtn = document.getElementById('add-task-btn');
    const clearCompletedBtn = document.getElementById('clear-completed');
    const allFilterBtn = document.getElementById('all-filter');
    const activeFilterBtn = document.getElementById('active-filter');
    const completedFilterBtn = document.getElementById('completed-filter');

    // Add task on button click
    addTaskBtn.addEventListener('click', () => {
      this.addTask(taskInput.value);
      taskInput.value = '';
      taskInput.focus();
    });

    // Add task on Enter key
    taskInput.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        this.addTask(taskInput.value);
        taskInput.value = '';
        taskInput.focus();
      }
    });

    // Clear completed tasks
    clearCompletedBtn.addEventListener('click', () => {
      this.clearCompleted();
    });

    // Filter buttons
    allFilterBtn.addEventListener('click', () => this.setFilter('all'));
    activeFilterBtn.addEventListener('click', () => this.setFilter('active'));
    completedFilterBtn.addEventListener('click', () => this.setFilter('completed'));
  }

  // Render tasks
  render() {
    const taskList = document.getElementById('task-list');
    const emptyState = document.getElementById('empty-state');
    const filteredTasks = this.getFilteredTasks();

    // Update filter button states
    document.querySelectorAll('.filter-btn').forEach(btn => {
      btn.classList.remove('active');
      if (btn.dataset.filter === this.currentFilter) {
        btn.classList.add('active');
      }
    });

    // Show/hide empty state
    if (filteredTasks.length === 0) {
      emptyState.style.display = 'block';
      taskList.innerHTML = '';
    } else {
      emptyState.style.display = 'none';

      // Render tasks
      taskList.innerHTML = filteredTasks.map(task => `
        <li class="task-item ${task.completed ? 'completed' : ''}" data-id="${task.id}">
          <input 
            type="checkbox" 
            class="task-checkbox" 
            ${task.completed ? 'checked' : ''}
            aria-label="Mark task as ${task.completed ? 'incomplete' : 'complete'}"
          >
          <span class="task-text">${this.escapeHtml(task.text)}</span>
          <div class="task-actions">
            <button class="delete-btn" aria-label="Delete task">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M19 7L18.1327 19.1429C18.0579 20.1891 17.187 21 16.14 21H7.86C6.813 21 5.94212 20.1891 5.86732 19.1429L5 7M10 11V17M14 11V17M17 7V4C17 3.44772 16.5523 3 16 3H8C7.44772 3 7 3.44772 7 4V7M3 7H21" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
              </svg>
            </button>
          </div>
        </li>
      `).join('');

      // Add event listeners to checkboxes and delete buttons
      document.querySelectorAll('.task-checkbox').forEach(checkbox => {
        checkbox.addEventListener('change', (e) => {
          const taskId = parseInt(e.target.closest('.task-item').dataset.id);
          this.toggleTask(taskId);
        });
      });

      document.querySelectorAll('.delete-btn').forEach(button => {
        button.addEventListener('click', (e) => {
          const taskId = parseInt(e.target.closest('.task-item').dataset.id);
          this.deleteTask(taskId);
        });
      });
    }
  }

  // Helper function to escape HTML
  escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }
}

